        "body": "Внешний ключ (FOREIGN KEY) задаёт ссылку из одной таблицы на ключ другой. Например, orders.customer_id может ссылаться на customers.customer_id. Это означает, что заказ не должен ссылаться на несуществующего клиента.\n\nВнешний ключ проверяет целостность связи при INSERT и UPDATE. Если попытаться записать customer_id, которого нет в customers, PostgreSQL отклонит операцию. Удаление родительской строки тоже может быть ограничено, если на неё ссылаются заказы.\n\nСвязь один-ко-многим: один клиент может иметь много заказов, но каждый заказ ссылается на одного клиента. Сам JOIN не создаёт и не проверяет такую связь: JOIN только сопоставляет строки во время запроса, а FOREIGN KEY защищает данные при изменениях.",
