        "body": "ORDER BY сортирует результат по одному или нескольким выражениям. ASC — по возрастанию, DESC — по убыванию. При нескольких критериях сначала сравнивается первый, при равенстве — второй. Можно сортировать по алиасу SELECT или номеру позиции, но имена выражений обычно читаемее.",
